  `pageId` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `leadgenId` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `formId` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `dedupeKey` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('received','pending','processing','imported','skipped','failed','ignored') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'received',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `leadId` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `retryCount` int NOT NULL DEFAULT '0',
  `lastError` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `nextAttemptAt` datetime DEFAULT NULL,
  `formName` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `pageName` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `campaignId` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
