  UNIQUE KEY `meta_webhook_ingestions_dedupe_uq` (`dedupeKey`),
  UNIQUE KEY `meta_webhook_ingestions_company_page_lead_uq` (`companyId`,`pageId`,`leadgenId`),
  KEY `metaPageId` (`metaPageId`),
  KEY `connectionId` (`connectionId`),
  KEY `meta_webhook_ingestions_company_id` (`companyId`),
  KEY `meta_webhook_ingestions_status_created_at` (`status`,`createdAt`),
  KEY `meta_webhook_ingestions_leadId_foreign_idx` (`leadId`),
  KEY `meta_webhook_ingestions_status_attempt_idx` (`status`,`nextAttemptAt`),
