  CONSTRAINT `meta_webhook_ingestions_ibfk_3` FOREIGN KEY (`connectionId`) REFERENCES `meta_connections` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `meta_webhook_ingestions_leadId_foreign_idx` FOREIGN KEY (`leadId`) REFERENCES `leads` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
