--
-- Table structure for table `meta_sync_jobs`
--

DROP TABLE IF EXISTS `meta_sync_jobs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `meta_sync_jobs` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `companyId` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `metaPageId` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `facebookPageId` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdByUserId` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('pending','processing','completed','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `since` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `formId` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `imported` int NOT NULL DEFAULT '0',
  `skipped` int NOT NULL DEFAULT '0',
  `failed` int NOT NULL DEFAULT '0',
  `pending` int NOT NULL DEFAULT '0',
  `formsTotal` int NOT NULL DEFAULT '0',
  `formsDone` int NOT NULL DEFAULT '0',
  `leadsSeen` int NOT NULL DEFAULT '0',
  `errorMessage` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `leaseOwner` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `startedAt` datetime DEFAULT NULL,
  `finishedAt` datetime DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `metaPageId` (`metaPageId`),
  KEY `createdByUserId` (`createdByUserId`),
  KEY `meta_sync_jobs_company_id` (`companyId`),
  KEY `meta_sync_jobs_company_page_status_idx` (`companyId`,`metaPageId`,`status`),
  KEY `meta_sync_jobs_status_created_idx` (`status`,`createdAt`),
  CONSTRAINT `meta_sync_jobs_ibfk_1` FOREIGN KEY (`companyId`) REFERENCES `companies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `meta_sync_jobs_ibfk_2` FOREIGN KEY (`metaPageId`) REFERENCES `meta_pages` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `meta_sync_jobs_ibfk_3` FOREIGN KEY (`createdByUserId`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

